"""JSON Merge Patch and JSON Patch application helpers."""
import copy


def merge_patch(target, patch):
    """Apply RFC 7386 merge patch and return a new JSON-compatible value."""
    if not isinstance(patch, dict):
        return copy.deepcopy(patch)
    out = copy.deepcopy(target) if isinstance(target, dict) else {}
    for key, value in patch.items():
        if value is None:
            out.pop(key, None)
        else:
            out[key] = merge_patch(out.get(key), value)
    return out


def _parts(pointer):
    if pointer == "":
        return []
    if not isinstance(pointer, str) or not pointer.startswith("/"):
        raise ValueError("invalid JSON pointer")
    return [p.replace("~1", "/").replace("~0", "~") for p in pointer[1:].split("/")]


def _get(root, path):
    cur = root
    for part in path:
        cur = cur[int(part)] if isinstance(cur, list) else cur[part]
    return cur


def _parent(root, path):
    if not path:
        return None, None
    return _get(root, path[:-1]), path[-1]


def _remove(root, path):
    if not path:
        return None
    parent, key = _parent(root, path)
    if isinstance(parent, list):
        return parent.pop(int(key))
    return parent.pop(key)


def _add(root, path, value):
    if not path:
        return copy.deepcopy(value)
    parent, key = _parent(root, path)
    value = copy.deepcopy(value)
    if isinstance(parent, list):
        if key == "-":
            parent.append(value)
        else:
            parent.insert(int(key), value)
    else:
        parent[key] = value
    return root


def apply_json_patch(document, operations):
    """Apply a JSON Patch sequence, returning a fresh document."""
    root = copy.deepcopy(document)
    for op in operations:
        kind = op.get("op")
        path = _parts(op.get("path"))
        if kind == "test":
            if _get(root, path) != op.get("value"):
                raise ValueError("JSON Patch test failed")
        elif kind == "remove":
            root = _remove(root, path)
        elif kind == "add":
            root = _add(root, path, op.get("value"))
        elif kind == "replace":
            _get(root, path)  # replacement requires an existing target
            if path:
                _remove(root, path)
            root = _add(root, path, op.get("value"))
        elif kind == "copy":
            value = copy.deepcopy(_get(root, _parts(op.get("from"))))
            root = _add(root, path, value)
        elif kind == "move":
            src = _parts(op.get("from"))
            value = _remove(root, src)
            root = _add(root, path, value)
        else:
            raise ValueError("unknown JSON Patch operation")
    return root

