"""Core renderer for the jd structural diff format."""
import json
from difflib import SequenceMatcher

def _normalize(v):
    if isinstance(v, float) and v.is_integer(): return int(v)
    if isinstance(v, list): return [_normalize(x) for x in v]
    if isinstance(v, dict): return {k: _normalize(x) for k, x in v.items()}
    return v

def _j(v):
    return json.dumps(_normalize(v), ensure_ascii=False, separators=(',', ':'), sort_keys=True)

def _equal(x, y):
    if isinstance(x, bool) or isinstance(y, bool):
        return isinstance(x, bool) and isinstance(y, bool) and x == y
    if isinstance(x, (int, float)) and isinstance(y, (int, float)):
        return x == y
    if isinstance(x, dict) and isinstance(y, dict):
        return x.keys() == y.keys() and all(_equal(x[k], y[k]) for k in x)
    if isinstance(x, list) and isinstance(y, list):
        return len(x) == len(y) and all(_equal(a, b) for a, b in zip(x, y))
    return type(x) is type(y) and x == y

def render_diff(a, b, base_path=None):
    hunks=[]
    if base_path is None: base_path=[]
    def atom(path, old, new):
        hunks.append('\n'.join(['@ '+_j(path), '- '+_j(old), '+ '+_j(new)]))
    def rec(path, x, y):
        if _equal(x, y): return
        if isinstance(x, dict) and isinstance(y, dict):
            for k in sorted(set(x)|set(y), key=lambda z: str(z)):
                if k not in y: hunks.append('@ '+_j(path+[k])+'\n- '+_j(x[k]))
                elif k not in x: hunks.append('@ '+_j(path+[k])+'\n+ '+_j(y[k]))
                else: rec(path+[k], x[k], y[k])
            return
        if isinstance(x, list) and isinstance(y, list):
            if len(x)==len(y) and any(isinstance(a,dict) and isinstance(b,dict) for a,b in zip(x,y)):
                for i,(u,v) in enumerate(zip(x,y)): rec(path+[i],u,v)
                return
            sm=SequenceMatcher(a=[_j(v) for v in x],b=[_j(v) for v in y],autojunk=False)
            ops=[]
            for tag,i1,i2,j1,j2 in sm.get_opcodes():
                if tag=='equal': ops.extend((' ',x[k]) for k in range(i1,i2))
                else:
                    ops.extend(('-',x[k]) for k in range(i1,i2));ops.extend(('+',y[k]) for k in range(j1,j2))
            if all(t==' ' for t,_ in ops):return
            first=next(i for i,z in enumerate(ops) if z[0]!=' '); last=max(i for i,z in enumerate(ops) if z[0]!=' ')
            # Separate change runs when unchanged elements divide them.
            runs=[]
            for oi,(tag,_) in enumerate(ops):
                if tag!=' ':
                    if not runs or oi>runs[-1][-1]+1:runs.append([oi])
                    else:runs[-1].append(oi)
            if len(runs)>1:
                for ri,run in enumerate(runs):
                    lo=max(0,run[0]-1); hi=min(len(ops),run[-1]+2)
                    start=sum(1 for t,_ in ops[:run[0]] if t in (' ','+'))
                    out=[]
                    out.append('@ '+_j(path+[start]))
                    if ri==0 and run[0]==0:out.append('[')
                    out.extend(('  ' if t==' ' else t+' ')+_j(v) for t,v in ops[lo:hi])
                    if ri==len(runs)-1 and run[-1]==len(ops)-1:out.append(']')
                    hunks.append('\n'.join(out))
                return
            # jd array hunks include the nearest item on either side as context.
            lo=max(0,first-1); hi=min(len(ops),last+2)
            selected=ops[lo:hi]
            changed_path=path+[sum(1 for t,_ in ops[:first] if t in (' ','+'))]
            out=['@ '+_j(changed_path)]
            if lo==0 and selected and selected[0][0]!=' ': out.append('[')
            out.extend(('  ' if t==' ' else t+' ')+_j(v) for t,v in selected)
            if last==len(ops)-1:out.append(']')
            hunks.append('\n'.join(out));return
        atom(path,x,y)
    rec(list(base_path),a,b)
    return '\n'.join(hunks)+('\n' if hunks else '')

