import json, math

def normalize(value):
    if isinstance(value, float) and value.is_integer() and abs(value)<1e21:
        return int(value)
    if isinstance(value, list): return [normalize(x) for x in value]
    if isinstance(value, dict): return {k: normalize(v) for k, v in value.items()}
    return value

def _float(v):
    if not math.isfinite(v): raise ValueError('unsupported non-finite number')
    s=repr(v).lower()
    if 'e' not in s:return s
    mant,ex=s.split('e'); exp=int(ex)
    # Go's encoder uses fixed notation for decimal exponents in [-6, 20].
    if -6<=exp<21:
        sign='';
        if mant.startswith('-'):sign='-';mant=mant[1:]
        if '.' in mant:
            whole,frac=mant.split('.')
        else: whole,frac=mant,''
        digits=whole+frac; point=len(whole)+exp
        if point<=0: out='0.'+'0'*(-point)+digits
        elif point>=len(digits):out=digits+'0'*(point-len(digits))
        else:out=digits[:point]+'.'+digits[point:]
        return sign+out
    return mant+'e'+('+' if exp>=0 else '-')+str(abs(exp))

def dumps(value, **kwargs):
    value=normalize(value)
