    separators=kwargs.pop('separators', None)
    if kwargs: return json.dumps(value,ensure_ascii=ensure_ascii,sort_keys=sort_keys,separators=separators,**kwargs)
    if separators is None: item_sep,key_sep=', ',': '
    else:item_sep,key_sep=separators
    def enc(v):
        if v is None:return 'null'
        if v is True:return 'true'
        if v is False:return 'false'
        if isinstance(v,str):return json.dumps(v,ensure_ascii=ensure_ascii)
        if isinstance(v,int):return str(v)
        if isinstance(v,float):return _float(v)
        if isinstance(v,list):return '['+item_sep.join(enc(x) for x in v)+']'
        if isinstance(v,dict):
